/// Returns the configured constant delay when `reconnect.mode = "fixed"`.
///
/// `reconnect.mode = "fixed"` is validated to carry a positive `interval_ms` while the
/// config is loaded, so a zero delay here would only come from a directly constructed
/// `Config`.
fn fixed_reconnect_delay(reconnect: &ReconnectConfigToml) -> Option<Duration> {
    match reconnect.mode {
        ReconnectMode::Default => None,
        ReconnectMode::Fixed => Some(Duration::from_millis(
            reconnect.interval_ms.unwrap_or_default(),
        )),
    }
}

